from __future__ import annotations

import re
from typing import Callable


def _value(record: dict, field: str) -> object:
    value = record.get(field, "")
    return "" if value is None else value


def _non_empty(record: dict, field: str) -> bool:
    return _value(record, field) != ""


def _evaluate_value(expression: str, record: dict) -> object:
    if not expression.startswith("="):
        return expression

    expr = expression[1:].strip()
    match = re.fullmatch(
        r"NVL\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*,\s*'([^']*)'\s*\)",
        expr,
        flags=re.IGNORECASE,
    )
    if match:
        field, default = match.groups()
        value = _value(record, field)
        return value if value != "" else default

    raise ValueError(f"Unsupported VRL expression: {expression}")


def _apply_actions(
    actions: tuple[tuple[str, str, str], ...],
    record: dict,
    audits: list[str],
    notifies: list[str],
) -> None:
    for action in actions:
        kind = action[0]
        if kind == "set":
            _, field, value = action
            record[field] = _evaluate_value(value, record)
        elif kind == "audit":
            audits.append(action[1])
        elif kind == "notify":
            notifies.append(action[1])


def fire(state: str, event: str, record: dict) -> dict:
    result_record = dict(record)
    audits: list[str] = []
    notifies: list[str] = []

    transition: tuple[str, Callable[[dict], bool], tuple[tuple[str, str, str], ...]] | None = None

    if state == "N" and event == "assign":
        transition = (
            "A",
            lambda current: _non_empty(current, "OWNER_UID"),
            (("audit", "CASE_ASSIGN", ""),),
        )
    elif state == "N" and event == "auto_escalate":
        transition = (
            "A",
            lambda current: True,
            (
                ("set", "ESC_FLG", "Y"),
                ("set", "SEV_CD", "=NVL(SEV_CD,'3')"),
                ("audit", "CASE_ESC", ""),
                ("notify", "escalation", ""),
            ),
        )
    elif state == "A" and event == "auto_escalate":
        transition = (
            "A",
            lambda current: _value(current, "ESC_FLG") != "Y",
            (
                ("set", "ESC_FLG", "Y"),
                ("audit", "CASE_ESC", ""),
                ("notify", "escalation", ""),
            ),
        )
    elif state == "A" and event == "await_customer":
        transition = (
            "P",
            lambda current: True,
            (("audit", "CASE_PEND", ""),),
        )
    elif state == "P" and event == "customer_reply":
        transition = ("A", lambda current: True, ())
    elif state == "A" and event == "resolve":
        transition = (
            "R",
            lambda current: _value(current, "RES_DT") != "00000000",
            (("audit", "CASE_RES", ""),),
        )
    elif state == "R" and event == "close":
        transition = (
            "X",
            lambda current: True,
            (("audit", "CASE_CLOSE", ""),),
        )
    elif state == "R" and event == "reopen":
        transition = (
            "A",
            lambda current: True,
            (
                ("set", "RES_DT", "00000000"),
                ("audit", "CASE_REOPEN", ""),
            ),
        )

    if transition is None or not transition[1](result_record):
        return {
            "state": state,
            "record": result_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    next_state, _, actions = transition
    _apply_actions(actions, result_record, audits, notifies)

    return {
        "state": next_state,
        "record": result_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
